/* 目标权重与风控规则：以 sqlite 里的配置为准；库里没有则从 config.js 导入一次（之后手动同步）。
   CFG/RULES/TARGETS 在 applyConfig() 里按来源刷新（DB 优先）。 */
const CFG_FROM_JS = window.PANEL_CONFIG || null;   // config.js（可能不存在）
let CFG = CFG_FROM_JS;                              // 当前生效配置（DB 或 JS）
const DEFAULT_RULES = {
  sh_ratio: 0.6, max_single: 25, max_ind: 35, lot: 100, capital: 100000,
  dev_warn: 3, skip_premium: 3, vol_warn: 25, ocf_min: 1
};
let RULES = Object.assign({}, DEFAULT_RULES, (CFG && CFG.rules) || {});
let TARGETS = (CFG && CFG.targets) || [];
const TGT = {};                                     // code -> target，applyConfig 时重建
/* 安全边际指标：页面启动时从公开接口实时计算填入（结构为 { "601000.SH": {...} }）。
   { "601000.SH": {targetBuyAbsolute, targetBuyConservative, yldPct, curYld, yldAvg, boll:[...]} } */
const MARGIN = {};

/* 应用一份配置：刷新 CFG/RULES/TARGETS/TGT（供 DB 优先加载与手动同步共用） */
function applyConfig(cfg) {
  CFG = cfg || null;
  RULES = Object.assign({}, DEFAULT_RULES, (CFG && CFG.rules) || {});
  TARGETS = (CFG && CFG.targets) || [];
  Object.keys(TGT).forEach(k => delete TGT[k]);
  TARGETS.forEach(t => { TGT[t.code] = t; });
  if (typeof fillCodeList === 'function') { try { fillCodeList(); } catch (e) {} }
}

