function saveSetting(k, v) {
  if (!db) return;
  S.settings[k] = v;
  db.run('INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)', [k, String(v)]);
  queueSave();
}

/* ===== 配置在 sqlite 中的存取（以 DB 为准；config.js 仅首次导入/手动同步） ===== */
const CFG_KEY = 'cfg';
function loadConfigFromDb() {
  // 读 setting 表里的 cfg（整份 PANEL_CONFIG 的 JSON）
  let raw = null;
  try { const rows = q("SELECT v FROM setting WHERE k=?", [CFG_KEY]); raw = rows.length ? rows[0].v : null; } catch (e) { raw = null; }
  if (raw) {
    try { applyConfig(JSON.parse(raw)); return 'db'; } catch (e) { console.warn('库内配置解析失败，回退 config.js', e); }
  }
  // 库内没有 → 首次从 config.js 导入并写库（若存在）
  if (CFG_FROM_JS) {
    try {
      db.run('INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)', [CFG_KEY, JSON.stringify(CFG_FROM_JS)]);
      queueSave();
      applyConfig(CFG_FROM_JS);
      return 'imported';
    } catch (e) { applyConfig(CFG_FROM_JS); return 'js'; }
  }
  applyConfig(null);
  return 'none';
}
/* 手动同步：用 config.js 覆盖库内配置（会丢弃库里的手改） */
function syncConfigFromJs() {
  if (!db) return { ok: false, msg: '数据库未打开' };
  if (!CFG_FROM_JS) return { ok: false, msg: '未找到 config.js（页面未加载到 PANEL_CONFIG）' };
  db.run('INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)', [CFG_KEY, JSON.stringify(CFG_FROM_JS)]);
  queueSave();
  applyConfig(CFG_FROM_JS);
  return { ok: true, msg: '已从 config.js 同步：' + (TARGETS.length) + ' 只目标' };
}

